css:
.marketsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2a23;
    background: linear-gradient(160deg, #f3f6ed 0%, #e7efe0 100%);
    border-radius: 18px;
}

.marketsim-container * {
    box-sizing: border-box;
}

.marketsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1d3b2a 0%, #2f5d3a 55%, #4a7c43 100%);
    color: #f1f8ec;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(29, 59, 42, 0.30);
}

.marketsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.marketsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #cfe8bf;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.marketsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e3f1da;
}

.marketsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2f5d3a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.marketsim-period-counter #currentDay,
.marketsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1d3b2a;
}

.marketsim-round-name {
    background: #d4e8c6;
    color: #1d3b2a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.marketsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3b14;
    background: #f7e2d4;
    padding: 4px 12px;
    border-radius: 999px;
}

.marketsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.marketsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d8e4cd;
    box-shadow: 0 4px 14px rgba(29, 59, 42, 0.06);
    border-top: 4px solid #4a7c43;
}

.marketsim-card-participants { border-top-color: #2f7d5b; }
.marketsim-card-legitimacy { border-top-color: #b07a17; }
.marketsim-card-capital { border-top-color: #2f6fb0; }
.marketsim-card-budget { border-top-color: #5a6b3a; }

.marketsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e7159;
}

.marketsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1d3b2a;
}

.marketsim-card-participants .marketsim-value { color: #2f7d5b; }
.marketsim-card-legitimacy .marketsim-value { color: #b07a17; }
.marketsim-card-capital .marketsim-value { color: #2f6fb0; }
.marketsim-card-budget .marketsim-value { color: #5a6b3a; }

.marketsim-sublabel {
    font-size: 0.76rem;
    color: #6f8369;
    line-height: 1.35;
}

.marketsim-participants-target .marketsim-value { color: #2f7d5b; }
.marketsim-participants-short .marketsim-value { color: #c0392b; }
.marketsim-capital-target .marketsim-value { color: #2f7d5b; }
.marketsim-capital-short .marketsim-value { color: #c0392b; }

.marketsim-budget-over { border-top-color: #c0392b; }
.marketsim-budget-over .marketsim-value { color: #c0392b; }

.marketsim-leverage-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1d3b2a;
    color: #eaf6e2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.marketsim-leverage-bar #leverageDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #bfe6a8;
}

.marketsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4a7c43;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(29, 59, 42, 0.05);
}

.marketsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.marketsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1d3b2a;
    margin-bottom: 6px;
}

.marketsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #354a30;
}

.marketsim-briefing-text strong { color: #2f7d5b; }
.marketsim-briefing-text em { color: #9a3b14; font-style: italic; }

.marketsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d8e4cd;
    box-shadow: 0 4px 14px rgba(29, 59, 42, 0.06);
}

.marketsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1d3b2a;
    border-bottom: 2px solid #e4eedb;
    padding-bottom: 8px;
}

.marketsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3f25;
    margin: 14px 0 6px;
}

.marketsim-container select,
.marketsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bfd4b0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7faf2;
    color: #1f2a23;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.marketsim-container select:focus,
.marketsim-container input[type="number"]:focus {
    outline: none;
    border-color: #4a7c43;
    box-shadow: 0 0 0 3px rgba(74, 124, 67, 0.16);
}

.marketsim-container select option {
    background-color: #ffffff;
    color: #1f2a23;
}

.marketsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4a7c43;
}

.marketsim-range-readout,
.marketsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f5d3a;
    margin-top: 4px;
}

.marketsim-range-readout span:last-child,
.marketsim-alloc-readout span:nth-child(2) {
    color: #2f7d5b;
    font-weight: 800;
}

.marketsim-hint {
    font-size: 0.8rem;
    color: #6f8369;
    margin-top: 4px;
    line-height: 1.4;
}

.marketsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.marketsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2f7ec;
    border: 1px solid #dbe8cf;
    border-radius: 9px;
    padding: 8px 12px;
}

.marketsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2a3f25;
}

.marketsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.marketsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.marketsim-container .btn-primary {
    background: linear-gradient(135deg, #2f7d5b 0%, #4a7c43 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 125, 91, 0.28);
}

.marketsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.marketsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bfd4b0;
    color: #5e7159;
}

.marketsim-coach {
    background: #1d3b2a;
    color: #eaf6e2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(29, 59, 42, 0.22);
}

.marketsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9fd185;
    margin-bottom: 8px;
}

.marketsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.marketsim-coach-body strong { color: #ffd98a; }
.marketsim-coach-body em { color: #ffc1ad; font-style: italic; }

.marketsim-history,
.marketsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d8e4cd;
    box-shadow: 0 4px 14px rgba(29, 59, 42, 0.06);
}

.marketsim-history h3,
.marketsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1d3b2a;
}

.marketsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a3f25;
}

.marketsim-container table#usfHistoryTable th {
    background: #ecf3e4;
    color: #1d3b2a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e5c9;
}

.marketsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4e7;
}

.marketsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbf4;
}

.marketsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .marketsim-container {
        padding: 14px;
    }
    .marketsim-header h1 {
        font-size: 1.7rem;
    }
    .marketsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .marketsim-value {
        font-size: 2rem;
    }
    .marketsim-clock {
        margin-left: 0;
    }
    .marketsim-period-counter {
        font-size: 0.88rem;
    }
    .marketsim-leverage-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .marketsim-alloc-row {
        flex-wrap: wrap;
    }
    .marketsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .marketsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.marketsim-completion { padding: 8px 4px 4px; }
.marketsim-cm-head { text-align: center; margin-bottom: 16px; }
.marketsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f7d5b; }
.marketsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5a7060; }
.marketsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #1d3b2a; }
.marketsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.marketsim-cm-yes { background: rgba(47,125,91,0.15); color: #256a4a; border: 1px solid rgba(47,125,91,0.42); }
.marketsim-cm-no { background: rgba(192,57,43,0.12); color: #c0392b; border: 1px solid rgba(192,57,43,0.4); }
.marketsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.marketsim-cm-metric { flex: 1 1 120px; min-width: 108px; background: #f2f7f2; border: 1px solid #d8e4cd; border-radius: 10px; padding: 10px 8px; text-align: center; }
.marketsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2f7d5b; }
.marketsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a7060; text-transform: uppercase; letter-spacing: 0.03em; }
.marketsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #1d3b2a; }
.marketsim-cm-insights { margin: 0; padding-left: 20px; }
.marketsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2a3f25; }

