(function() {
    'use strict';

    class MarketAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Building the Market`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_PARTICIPANTS = 4;     // current binding adopters
            this.TARGET_PARTICIPANTS = 25;   // 12-month ecosystem-participant goal
            this.START_LEGITIMACY = 22;      // fragile after the flagship collapse
            this.START_CAPITAL = 12;         // GBP 12M private capital to date, in £M
            this.TARGET_CAPITAL = 75;        // GBP 75M committed private finance goal
            this.BUDGET_CAP = 6.5;           // GBP 6.5M catalytic fund, in £M

            // Concept truths (build the institutions, in the right order, openly).
            this.TRUE_GAP = `standard`;
            this.TRUE_LENS = `orchestrator`;
            this.TRUE_FIRST = `standard`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    participants: this.START_PARTICIPANTS,
                    legitimacy: this.START_LEGITIMACY,
                    capital: this.START_CAPITAL,
                    grantCapital: 0,
                    privateCapital: this.START_CAPITAL,
                    budgetUsed: 0,
                    targetMissed: false,
                    captured: false,
                    pilotMarket: false,
                    complianceWithChain: false,
                    participantsHistory: [this.START_PARTICIPANTS],
                    legitimacyHistory: [this.START_LEGITIMACY],
                    capitalHistory: [this.START_CAPITAL],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    gap: `standard`,
                    lens: `orchestrator`,
                    diagnosis: 60,
                    first: `standard`,
                    allocStandard: 3.0,
                    allocInsurance: 2.0,
                    allocCoalition: 1.0,
                    allocSubsidy: 0.5,
                    dependency: `sequence`,
                    anchor: `insurer`,
                    stance: `open`,
                    rival: `converge`,
                    inclusion: 60,
                    capitalStruct: `firstloss`,
                    evidence: `multiactor`,
                    target: 80,
                    defence: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gap = document.getElementById(`gapInput`);
                const lens = document.getElementById(`lensInput`);
                const diag = document.getElementById(`diagnosisInput`);
                if (gap) decisions.gap = gap.value;
                if (lens) decisions.lens = lens.value;
                if (diag) decisions.diagnosis = parseInt(diag.value, 10);
                if (!Number.isFinite(decisions.diagnosis) || decisions.diagnosis < 0 || decisions.diagnosis > 100) {
                    warn(`warn_diagnosis_range`); return false;
                }
            } else if (round === 2) {
                const first = document.getElementById(`firstInput`);
                const dep = document.getElementById(`dependencyInput`);
                if (first) decisions.first = first.value;
                if (dep) decisions.dependency = dep.value;
                const st = document.getElementById(`allocStandardInput`);
                const ins = document.getElementById(`allocInsuranceInput`);
                const co = document.getElementById(`allocCoalitionInput`);
                const su = document.getElementById(`allocSubsidyInput`);
                if (st) decisions.allocStandard = parseFloat(st.value);
                if (ins) decisions.allocInsurance = parseFloat(ins.value);
                if (co) decisions.allocCoalition = parseFloat(co.value);
                if (su) decisions.allocSubsidy = parseFloat(su.value);
                const parts = [decisions.allocStandard, decisions.allocInsurance, decisions.allocCoalition, decisions.allocSubsidy];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.allocStandard + decisions.allocInsurance + decisions.allocCoalition + decisions.allocSubsidy) * 10) / 10;
                if (Math.abs(total - this.BUDGET_CAP) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const an = document.getElementById(`anchorInput`);
                const stn = document.getElementById(`stanceInput`);
                const rv = document.getElementById(`rivalInput`);
                const inc = document.getElementById(`inclusionInput`);
                if (an) decisions.anchor = an.value;
                if (stn) decisions.stance = stn.value;
                if (rv) decisions.rival = rv.value;
                if (inc) decisions.inclusion = parseInt(inc.value, 10);
                if (!Number.isFinite(decisions.inclusion) || decisions.inclusion < 0 || decisions.inclusion > 100) {
                    warn(`warn_inclusion_range`); return false;
                }
            } else if (round === 4) {
                const cs = document.getElementById(`capitalStructInput`);
                const ev = document.getElementById(`evidenceInput`);
                const tg = document.getElementById(`targetInput`);
                const df = document.getElementById(`defenceInput`);
                if (cs) decisions.capitalStruct = cs.value;
                if (ev) decisions.evidence = ev.value;
                if (tg) decisions.target = parseFloat(tg.value);
                if (df) decisions.defence = parseInt(df.value, 10);
                if (!Number.isFinite(decisions.target) || decisions.target < 0) {
                    warn(`warn_target_negative`); return false;
                }
                if (!Number.isFinite(decisions.defence) || decisions.defence < 0 || decisions.defence > 100) {
                    warn(`warn_defence_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: legitimacy = co-produced standard credibility (the scarce resource);
            // participantsDelta = net new ecosystem actors; privateDelta / grantDelta = capital
            // mobilised, split by source; spend = catalytic budget consumed (£M).
            let legitimacyDelta = 0, participantsDelta = 0, privateDelta = 0, grantDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the binding INSTITUTIONAL gap, not a promotion/technology/price gap
                // (Common Error 1: acting like a product company).
                if (d.gap === this.TRUE_GAP) {
                    legitimacyDelta += 10; participantsDelta += 1; coachKey = `coach_r1_gap_right`;
                } else if (d.gap === `awareness`) {
                    legitimacyDelta -= 8; coachKey = `coach_r1_awareness`;
                } else if (d.gap === `technology`) {
                    legitimacyDelta -= 6; coachKey = `coach_r1_technology`;
                } else {
                    legitimacyDelta -= 8; coachKey = `coach_r1_price`;
                }

                // The systems-change lens: Verdebuild is a system orchestrator, not a producer.
                if (d.lens === this.TRUE_LENS) {
                    legitimacyDelta += 9;
                    if (d.gap === this.TRUE_GAP) coachKey = `coach_r1_diag_sharp`;
                } else if (d.lens === `promoter`) {
                    legitimacyDelta -= 7; coachKey = `coach_r1_promoter`;
                } else if (d.lens === `producer`) {
                    legitimacyDelta -= 9; coachKey = `coach_r1_producer`;
                } else {
                    legitimacyDelta -= 6; coachKey = `coach_r1_charity`;
                }

                // Rigour of the diagnosis.
                if (d.diagnosis >= 60) { legitimacyDelta += 6; }
                else if (d.diagnosis <= 25) { legitimacyDelta -= 6; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.gap === this.TRUE_GAP && d.lens === this.TRUE_LENS) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the highest-leverage gap & sequence the rest (Common Error 2: everything at once).
                switch (d.first) {
                    case `standard`: legitimacyDelta += 12; participantsDelta += 2; coachKey = `coach_r2_standardfirst`; break;
                    case `insurance`: legitimacyDelta += 4; coachKey = `coach_r2_insurancefirst`; break;
                    case `finance`: legitimacyDelta -= 8; coachKey = `coach_r2_financefirst`; break;
                    case `everything`: legitimacyDelta -= 12; participantsDelta -= 1; coachKey = `coach_r2_everything`; break;
                }

                // Budget allocation: standard + insurance are the leverage points; coalition convening
                // builds legitimacy; direct subsidy is Verdebuild trying to buy a market (Common Error:
                // subsidising rather than catalysing).
                spend = d.allocStandard + d.allocInsurance + d.allocCoalition + d.allocSubsidy;
                if (d.allocStandard >= 2.0) legitimacyDelta += 6;
                else if (d.allocStandard < 1.0) { legitimacyDelta -= 6; coachKey = `coach_r2_understandard`; }
                if (d.allocInsurance >= 1.5) legitimacyDelta += 4;
                if (d.allocCoalition >= 0.8) legitimacyDelta += 4;
                else { legitimacyDelta -= 3; }
                if (d.allocSubsidy >= 2.0) { legitimacyDelta -= 8; coachKey = `coach_r2_subsidy`; }

                // Respect the dependency chain standard -> insurance -> finance.
                switch (d.dependency) {
                    case `sequence`: legitimacyDelta += 8; ds.complianceWithChain = true; coachKey = (d.first === `standard`) ? `coach_r2_sequenced` : coachKey; break;
                    case `parallel`: legitimacyDelta -= 3; break;
                    case `ignore`: legitimacyDelta -= 8; coachKey = `coach_r2_ignorechain`; break;
                }

                summaryKey = (d.first === `standard` && d.dependency === `sequence` && d.allocSubsidy < 2.0) ? `sum_r2_good` : (d.first === `everything` ? `sum_r2_spread` : `sum_r2_weak`);
            } else if (round === 3) {
                // Recruit the coalition & set the standard (Common Errors 3 & 4).
                // Anchor: the insurer who walked away and the regulator-as-legitimiser co-produce
                // legitimacy; co-opting the big manufacturer first risks capture.
                switch (d.anchor) {
                    case `insurer`: legitimacyDelta += 12; participantsDelta += 3; coachKey = `coach_r3_insurer`; break;
                    case `regulator`: legitimacyDelta += 9; participantsDelta += 2; coachKey = `coach_r3_regulator`; break;
                    case `developer`: legitimacyDelta += 2; participantsDelta += 1; coachKey = `coach_r3_developer`; break;
                    case `bigmanufacturer`: legitimacyDelta -= 4; participantsDelta += 2; coachKey = `coach_r3_bigmanu`; break;
                }

                // Open vs proprietary stance (Common Error 4: proprietary capture for a quick win).
                switch (d.stance) {
                    case `open`: legitimacyDelta += 10; participantsDelta += 4; coachKey = (d.anchor === `insurer`) ? `coach_r3_openinsurer` : coachKey; break;
                    case `hybrid`: legitimacyDelta += 12; participantsDelta += 5; coachKey = `coach_r3_hybrid`; break;
                    case `proprietary`: legitimacyDelta -= 12; participantsDelta -= 2; ds.captured = true; coachKey = `coach_r3_proprietary`; break;
                }

                // Handling the rival proto-standard.
                switch (d.rival) {
                    case `converge`: legitimacyDelta += 8; participantsDelta += 3; break;
                    case `outcompete`: legitimacyDelta += 4; participantsDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_outcompete` : coachKey; break;
                    case `capitulate`: legitimacyDelta -= 10; participantsDelta -= 1; ds.captured = true; coachKey = `coach_r3_capitulate`; break;
                }

                // Co-production breadth with the demand side (legitimacy is co-produced, not authored).
                if (d.inclusion >= 60) { legitimacyDelta += 6; participantsDelta += 3; }
                else if (d.inclusion <= 25) { legitimacyDelta -= 8; participantsDelta -= 1; coachKey = `coach_r3_authored`; }

                summaryKey = ((d.stance === `open` || d.stance === `hybrid`) && d.anchor !== `bigmanufacturer` && d.rival !== `capitulate`) ? `sum_r3_good` : (ds.captured ? `sum_r3_captured` : `sum_r3_weak`);
            } else if (round === 4) {
                // Mobilise catalytic capital that crowds in private finance & prove formation
                // (Common Errors 5 & 6).
                switch (d.capitalStruct) {
                    case `firstloss`: legitimacyDelta += 6; coachKey = `coach_r4_firstloss`; break;
                    case `grants`: legitimacyDelta -= 6; coachKey = `coach_r4_grants`; break;
                    case `direct`: legitimacyDelta -= 4; coachKey = `coach_r4_direct`; break;
                }

                // Evidence of formation (multi-actor uptake vs one MOU vs a soft pipeline).
                switch (d.evidence) {
                    case `multiactor`: legitimacyDelta += 10; participantsDelta += 5; coachKey = (d.capitalStruct === `firstloss`) ? `coach_r4_multiactor` : coachKey; break;
                    case `onemou`: legitimacyDelta -= 10; coachKey = `coach_r4_onemou`; ds.pilotMarket = true; break;
                    case `pipeline`: legitimacyDelta -= 4; participantsDelta += 1; coachKey = `coach_r4_pipeline`; break;
                }

                // The committed private-capital figure. First-loss de-risking crowds in private money;
                // grants do not count as a forming market (the leverage logic, ~1:11 target).
                if (d.capitalStruct === `firstloss`) {
                    // Catalytic budget de-risks ~11x of private finance, capped by the target committed.
                    privateDelta = Math.min(d.target, 70);
                    if (d.target >= 63) participantsDelta += 4;
                } else if (d.capitalStruct === `grants`) {
                    grantDelta = Math.min(d.target, 65);
                    privateDelta = Math.min(d.target * 0.18, 14);
                } else {
                    privateDelta = Math.min(d.target * 0.35, 24);
                }

                // Defence of the crowding-in logic.
                if (d.defence >= 60) { legitimacyDelta += 4; }
                else if (d.defence <= 25) { legitimacyDelta -= 4; }

                summaryKey = (d.capitalStruct === `firstloss` && d.evidence === `multiactor`) ? `sum_r4_good` : (d.evidence === `onemou` ? `sum_r4_pilot` : `sum_r4_weak`);
            }

            // Resource accounting.
            ds.budgetUsed = Math.round(Math.min(this.BUDGET_CAP, ds.budgetUsed + spend) * 10) / 10;

            // Legitimacy (the scarce resource) and participants move on their deltas.
            ds.legitimacy = Math.max(0, Math.min(100, ds.legitimacy + legitimacyDelta));
            ds.participants = Math.max(0, Math.round(ds.participants + participantsDelta));

            // Capital is split into genuine private finance (counts as market formation) and grants
            // (mobilised money that does not prove a market). Private growth is dampened when legitimacy
            // is low — capital only crowds in once the institutions de-risk participation.
            const legitFactor = 0.5 + (ds.legitimacy / 100) * 0.5;
            ds.privateCapital = Math.max(0, Math.round((ds.privateCapital + privateDelta * legitFactor) * 10) / 10);
            ds.grantCapital = Math.max(0, Math.round((ds.grantCapital + grantDelta) * 10) / 10);
            ds.capital = Math.round((ds.privateCapital + ds.grantCapital) * 10) / 10;

            ds.participantsHistory.push(ds.participants);
            ds.legitimacyHistory.push(Math.round(ds.legitimacy));
            ds.capitalHistory.push(Math.round(ds.privateCapital));

            if (round === this.ROUNDS.length) {
                if (ds.participants < this.TARGET_PARTICIPANTS || ds.privateCapital < this.TARGET_CAPITAL) ds.targetMissed = true;
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                participants: ds.participants,
                participantsDelta: participantsDelta,
                legitimacy: Math.round(ds.legitimacy),
                legitimacyDelta: Math.round(legitimacyDelta),
                privateCapital: Math.round(ds.privateCapital),
                grantCapital: Math.round(ds.grantCapital),
                budgetUsed: ds.budgetUsed,
                captured: ds.captured,
                pilotMarket: ds.pilotMarket,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`participantsDisplay`, `domainState.participants`, (v) => {
                const card = document.querySelector(`.marketsim-card-participants`);
                if (card) {
                    card.classList.toggle(`marketsim-participants-target`, Number(v) >= this.TARGET_PARTICIPANTS);
                    card.classList.toggle(`marketsim-participants-short`, Number(v) < this.TARGET_PARTICIPANTS);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`legitimacyDisplay`, `domainState.legitimacy`, (v) => Math.round(Number(v)));
            uiManager.bind(`capitalDisplay`, `domainState.privateCapital`, (v) => {
