                return `£` + Math.round(Number(v)) + `M`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.marketsim-card-budget`);
                if (card) card.classList.toggle(`marketsim-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return `£` + Number(v).toFixed(1) + `M / £6.5M`;
            });

            // Leverage bar: catalytic budget committed vs private capital mobilised.
            uiManager.bind(`leverageDisplay`, `domainState.privateCapital`, (v) => {
                const ds = window.mySimulation.state.domainState;
                const spent = Math.max(0.5, Number(ds.budgetUsed) || 0);
                const ratio = (Number(v) - this.START_CAPITAL) / spent;
                const shown = ratio > 0 ? ratio.toFixed(1) : `0.0`;
                return `1 : ` + shown;
