        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.participantsHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                marketChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.participantsHistory },
                        { data: ds.legitimacyHistory },
                        { data: ds.capitalHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Written to domainState.performance.overallScore each period for
        // the reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const participants = Math.round(ds.participants || 0);
            const legitimacy = Math.round(ds.legitimacy || 0);
            const privateCapital = Math.round(ds.privateCapital || 0);
            const composite = Math.round(
                Math.min(100, (participants / this.TARGET_PARTICIPANTS) * 100) * 0.35 +
                legitimacy * 0.30 +
                Math.min(100, (privateCapital / this.TARGET_CAPITAL) * 100) * 0.35
            );
            return Math.max(0, Math.min(100, composite));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const participants = Math.round(ds.participants);
            const legitimacy = Math.round(ds.legitimacy);
            const privateCapital = Math.round(ds.privateCapital);

            const hitParticipants = participants >= this.TARGET_PARTICIPANTS;
            const hitCapital = privateCapital >= this.TARGET_CAPITAL;
            const realFormation = hitParticipants && hitCapital && legitimacy >= 60 && !ds.captured;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            let performanceKey = `grade_niche`;
            if (realFormation && composite >= 78) performanceKey = `grade_formed`;
            else if (realFormation) performanceKey = `grade_credible`;
            else if (ds.captured && (hitParticipants || hitCapital)) performanceKey = `grade_captured`;
            else if (ds.pilotMarket || (hitCapital && participants < 12)) performanceKey = `grade_onemou`;
            else if (hitParticipants || hitCapital) performanceKey = `grade_incomplete`;
            const performance = T(performanceKey);

            const insights = [];
            if (realFormation) insights.push(window.mySimulation.t(`insight_formed`));
            else if (ds.captured) insights.push(window.mySimulation.t(`insight_captured`));
            else if (ds.pilotMarket) insights.push(window.mySimulation.t(`insight_onemou`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (legitimacy < 45) insights.push(window.mySimulation.t(`insight_lowlegit`));
            if (ds.grantCapital > ds.privateCapital * 0.8) insights.push(window.mySimulation.t(`insight_grantheavy`));
            if (!ds.complianceWithChain) insights.push(window.mySimulation.t(`insight_nochain`));
            if (realFormation && legitimacy >= 70) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                participants: participants,
                legitimacy: legitimacy,
                privateCapital: privateCapital,
                grantCapital: Math.round(ds.grantCapital),
                hitParticipants: hitParticipants,
                hitCapital: hitCapital,
                captured: ds.captured,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        // v1.1.0: render the computed grade, KPIs and insight debrief in the completion modal
        // instead of the framework generic "you completed N periods" fallback.
        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.hitParticipants && s.hitCapital);
            const badge = met
                ? `<span class="marketsim-cm-badge marketsim-cm-yes">` + T(`cm_targets_met`) + `</span>`
                : `<span class="marketsim-cm-badge marketsim-cm-no">` + T(`cm_targets_missed`) + `</span>`;
            const capturedBadge = s.captured
                ? ` <span class="marketsim-cm-badge marketsim-cm-no">` + T(`cm_captured`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="marketsim-cm-metric"><span class="marketsim-cm-mv">` + Math.round(s.participants || 0) + `</span><span class="marketsim-cm-ml">` + T(`cm_m_participants`) + `</span></div>`
                + `<div class="marketsim-cm-metric"><span class="marketsim-cm-mv">` + Math.round(s.legitimacy || 0) + `</span><span class="marketsim-cm-ml">` + T(`cm_m_legitimacy`) + `</span></div>`
                + `<div class="marketsim-cm-metric"><span class="marketsim-cm-mv">\u00a3` + Math.round(s.privateCapital || 0) + `M</span><span class="marketsim-cm-ml">` + T(`cm_m_capital`) + `</span></div>`
                + `<div class="marketsim-cm-metric"><span class="marketsim-cm-mv">\u00a3` + Math.round(s.grantCapital || 0) + `M</span><span class="marketsim-cm-ml">` + T(`cm_m_grant`) + `</span></div>`;
            return ``
                + `<div class="marketsim-completion">`
                +   `<div class="marketsim-cm-head">`
                +     `<div class="marketsim-cm-score">` + score + `<span class="marketsim-cm-score-max">/100</span></div>`
                +     `<div class="marketsim-cm-grade">` + grade + ` ` + badge + capturedBadge + `</div>`
                +   `</div>`
                +   `<div class="marketsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="marketsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="marketsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.captured) return window.mySimulation.t(`hint_captured`);
            if (ds.pilotMarket) return window.mySimulation.t(`hint_onemou`);
            if (ds.legitimacy < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_legit`);
            if (state.currentPeriod >= 3 && ds.participants < 12) return window.mySimulation.t(`hint_behind`);
            if (ds.participants >= this.TARGET_PARTICIPANTS && ds.privateCapital >= this.TARGET_CAPITAL && ds.legitimacy >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

